const payload = $json.body ?? $json;
const reflection = payload.reflection ?? {};
const recipient = payload.recipient ?? {};
const channels = recipient.channels ?? {};
const telegram = recipient.telegram ?? {};

function toText(value, fallback = '-') {
  if (typeof value === 'string') {
    const trimmed = value.trim();
    return trimmed || fallback;
  }

  if (value === null || value === undefined) {
    return fallback;
  }

  return String(value);
}

function toRank(value) {
  const number = Number(value);
  return Number.isFinite(number) ? String(number) : '-';
}

function escapeHtml(value) {
  return toText(value, '-')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function escapePdfText(value) {
  return toText(value, '-')
    .split('\\').join('\\\\')
    .split('(').join('\\(')
    .split(')').join('\\)');
}

function wrapText(input, maxWidth = 92) {
  const source = toText(input, '-').replaceAll('\r', '');
  const paragraphs = source.split('\n');
  const lines = [];

  for (const paragraph of paragraphs) {
    const words = paragraph.trim().split(/\s+/).filter(Boolean);
    if (!words.length) {
      lines.push('');
      continue;
    }

    let current = '';
    for (const word of words) {
      const candidate = current ? `${current} ${word}` : word;
      if (candidate.length <= maxWidth) {
        current = candidate;
      } else {
        if (current) {
          lines.push(current);
        }
        current = word;
      }
    }

    if (current) {
      lines.push(current);
    }
  }

  return lines.length ? lines : ['-'];
}

function buildPdfBase64(lines) {
  const streamLines = ['BT', '/F1 8 Tf', '10 TL', '40 780 Td'];

  lines.slice(0, 65).forEach((line, index, items) => {
    if (line.length > 0) {
      streamLines.push(`(${escapePdfText(line)}) Tj`);
    }
    if (index < items.length - 1) {
      streamLines.push('T*');
    }
  });

  streamLines.push('ET');

  const stream = streamLines.join('\n');
  const objects = [
    '1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj',
    '2 0 obj\n<< /Type /Pages /Count 1 /Kids [3 0 R] >>\nendobj',
    '3 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents 4 0 R /Resources << /Font << /F1 5 0 R >> >> >>\nendobj',
    `4 0 obj\n<< /Length ${Buffer.byteLength(stream, 'utf8')} >>\nstream\n${stream}\nendstream\nendobj`,
    '5 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>\nendobj'
  ];

  let pdf = '%PDF-1.4\n';
  const offsets = [0];

  for (const object of objects) {
    offsets.push(Buffer.byteLength(pdf, 'utf8'));
    pdf += object + '\n';
  }

  const xrefOffset = Buffer.byteLength(pdf, 'utf8');
  pdf += `xref\n0 ${objects.length + 1}\n`;
  pdf += '0000000000 65535 f \n';
  for (const offset of offsets.slice(1)) {
    pdf += `${String(offset).padStart(10, '0')} 00000 n \n`;
  }
  pdf += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF`;

  return Buffer.from(pdf, 'utf8').toString('base64');
}

const fullName = toText(reflection.full_name || recipient.display_name, 'Unknown Employee');
const departmentRole = toText(reflection.department_role);
const monthKey = toText(reflection.month_key);
const submittedAt = toText(payload.submitted_at);
const fileSlug = fullName.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '') || 'submission';
const pdfFileName = `five-percent-reflection-${fileSlug}-${monthKey}.pdf`;

const pdfLines = [
  'Control Hub 5% Reflection',
  '',
  `Employee: ${fullName}`,
  `Department/Role: ${departmentRole}`,
  `Month: ${monthKey}`,
  `Submitted At: ${submittedAt}`,
  '',
  'WORK',
  ...wrapText(`Feelings: ${reflection.work?.feelings}`),
  ...wrapText(`Headline: ${reflection.work?.headline}`),
  ...wrapText(`Why it mattered: ${reflection.work?.significance}`),
  ...wrapText(`Rank: ${toRank(reflection.work?.rank)}`),
  ...wrapText(`Next action: ${reflection.work?.action}`),
  '',
  'FAMILY',
  ...wrapText(`Feelings: ${reflection.family?.feelings}`),
  ...wrapText(`Headline: ${reflection.family?.headline}`),
  ...wrapText(`Why it mattered: ${reflection.family?.significance}`),
  ...wrapText(`Rank: ${toRank(reflection.family?.rank)}`),
  ...wrapText(`Next action: ${reflection.family?.action}`),
  '',
  'PERSONAL',
  ...wrapText(`Feelings: ${reflection.personal?.feelings}`),
  ...wrapText(`Headline: ${reflection.personal?.headline}`),
  ...wrapText(`Why it mattered: ${reflection.personal?.significance}`),
  ...wrapText(`Rank: ${toRank(reflection.personal?.rank)}`),
  ...wrapText(`Next action: ${reflection.personal?.action}`),
  '',
  'DEEP DIVE PARKING LOT',
  ...wrapText(reflection.deep_dive_parking_lot),
  '',
  'EXPLORATION TOPICS',
  ...wrapText(reflection.exploration_topics)
].slice(0, 65);

const emailHtml = [
  `<p>Hello ${escapeHtml(recipient.first_name || fullName)},</p>`,
  '<p>Attached is the PDF copy of your submitted 5% Reflection.</p>',
  '<p><b>Summary</b></p>',
  `<ul><li><b>Month:</b> ${escapeHtml(monthKey)}</li><li><b>Submitted at:</b> ${escapeHtml(submittedAt)}</li><li><b>Department/Role:</b> ${escapeHtml(departmentRole)}</li></ul>`,
  '<p>You can also review it in Control Hub.</p>'
].join('');

const adminTelegramText = [
  '<b>5% Reflection Submitted</b>',
  '',
  `<b>Employee:</b> ${escapeHtml(fullName)}`,
  `<b>Month:</b> ${escapeHtml(monthKey)}`,
  `<b>Department/Role:</b> ${escapeHtml(departmentRole)}`,
  '',
  'User delivery workflow prepared.',
  'https://app.sngroup.com.au/performance/self-evaluation'
].join('\n');

const telegramCaption = [
  '<b>Your 5% Reflection PDF</b>',
  `<b>Month:</b> ${escapeHtml(monthKey)}`
].join('\n');

return [{
  json: {
    ...payload,
    reflection,
    recipient: {
      ...recipient,
      channels: {
        gmail: Boolean(channels.gmail),
        telegram: Boolean(channels.telegram)
      },
      telegram: {
        ...telegram,
        chat_id: telegram.chat_id ? String(telegram.chat_id) : null
      }
    },
    pdfBase64: buildPdfBase64(pdfLines),
    pdfFileName,
    emailSubject: `Your 5% Reflection PDF - ${monthKey}`,
    emailHtml,
    telegramCaption,
    adminTelegramText
  }
}];
